        this.generateStatements(stmt.body, indent + this.options.indent);
        this.loopExitLabelStack.pop();
        this.emitLineDirective(stmt.sourceSpan.endLine);
        const closingLine = this.currentLine;
        this.emit(`${indent}}`);
        if (exitLabel.used)
            this.emit(`${indent}${exitLabel.name}: ;`);
