        if (nameUpper === "SUPER" && this.currentFBExtends) {
            const args = expr.arguments.map((arg) => this.generateExpression(arg.value));
            return `${this.currentFBExtends}::operator()(${args.join(", ")})`;
        }
        // 0. ADR(x) → &(x) (CODESYS address-of operator)
        if (nameUpper === "ADR") {
            const args = expr.arguments.map((arg) => this.generateExpression(arg.value));
            return `&(${args[0] ?? ""})`;
        }
